const { join } = require('path')
const cds = require('../../../cds')
const { read, write, exists, copy } = cds.utils
const { readProject } = require('../../projectReader')
const { merge, sort } = require('../../merge')
const mvn = require('../../mvn')

const { srv4, hdbDeployer, mtxSidecar4 } = require('../../registries/mta')

const serverlessDb = {
    in: 'resources',
    where: { type: 'org.cloudfoundry.managed-service', 'parameters.service': 'hana-cloud', 'parameters.service-plan': 'serverless' }
}

const identity = {
    in: 'resources',
    where: { type: 'org.cloudfoundry.managed-service', 'parameters.service': 'identity' }
}

module.exports = class HanaServerlessTemplate extends require('../../plugin') {

    static help() {
        return 'database support for SAP HANA Cloud serverless'
    }

    static hasInProduction(env) {
        return cds.cli.options?.add?.has('hana-serverless')
            || env.requires?.db?.kind === 'hana-serverless'
            || env.requires?.db?.serverless
    }

    async run() {
        const project = readProject()
        const { isJava, configFile, db } = project
        project.shortcut = !exists(configFile) || typeof (await read(configFile)).cds?.requires?.db !== 'object'

        if (isJava) {
            await copy(join(__dirname, 'files', 'db')).to(db.folder)
            await mvn.add('hana')
        }

        await merge(__dirname, 'files/package.json.hbs').into(configFile, { with: project, forceOverwrite: true })

        const packageJson = exists('package.json') ? await read('package.json') : null
        if (packageJson?.dependencies) {
            delete packageJson.dependencies['@sap/hana-client']
            await write('package.json', packageJson, { spaces: 2 })
        }
        await sort('package.json', 'dependencies')
    }

    async combine(facet) {
        const project = readProject(facet)
        const { addMta, hasMta, addMultitenancy, addKyma, isJava, hasMultitenancy, srv } = project

        if (addMta || addMultitenancy && hasMta) {
            const existingIdentity = await this._existingIdentityName()
            const srvModule = srv4(srv.path)

            const relationships = [{
                insert: [serverlessDb, 'name'],
                into: [srvModule, 'requires', 'name']
            }]
            if (!existingIdentity) relationships.push({
                insert: [identity, 'name'],
                into: [srvModule, 'requires', 'name']
            })

            if (hasMultitenancy) {
                const sidecar = mtxSidecar4(isJava ? 'mtx/sidecar' : 'gen/mtx/sidecar')
                relationships.push({
                    insert: [serverlessDb, 'name'],
                    into: [sidecar, 'requires', 'name']
                })
                if (!existingIdentity) relationships.push({
                    insert: [identity, 'name'],
                    into: [sidecar, 'requires', 'name']
                })
            } else {
                relationships.push({
                    insert: [serverlessDb, 'name'],
                    into: [hdbDeployer, 'requires', 'name']
                })
                if (!existingIdentity) relationships.push({
                    insert: [identity, 'name'],
                    into: [hdbDeployer, 'requires', 'name']
                })
            }

            const modules = hasMultitenancy ? [srvModule] : [srvModule, hdbDeployer]
            const additions = [...modules, serverlessDb]
            if (!existingIdentity) additions.push(identity)
            await merge(__dirname, 'files/mta.yaml.hbs').into('mta.yaml', {
                with: project, additions, relationships
            })

            if (existingIdentity) await this._consumeServerlessFrom(existingIdentity)

            if (hasMultitenancy) await this._alignSidecarDbKind()
        }

        if (addKyma) {
            const KymaTemplate = require('../kyma')
            const existingIdentity = await this._existingIdentityInChart()

            await merge(__dirname, 'files/values.yaml.hbs').into('chart/values.yaml', { with: project })

            if (existingIdentity) {
                await this._consumeServerlessInChart(existingIdentity)
            } else {
                await merge(__dirname, 'files/identity.values.yaml.hbs').into('chart/values.yaml', { with: project })
                await KymaTemplate.mergeDependency('service-instance', 'identity')
            }

            if (hasMultitenancy) await this._alignSidecarDbKind()
        }
    }

    async _existingIdentityInChart() {
        const { readYAML } = require('../../../util/fs')
        const doc = await readYAML('chart/values.yaml')
        if (!doc) return undefined
        const js = doc.toJS?.() ?? doc
        const identity = js?.identity
        if (identity && identity.serviceOfferingName === 'identity') return 'identity'
        return undefined
    }

    async _consumeServerlessInChart(identityKey) {
        const { readYAML, writeYAML } = require('../../../util/fs')
        const doc = await readYAML('chart/values.yaml')
        if (!doc) return
        const js = doc.toJS()
        const identity = js[identityKey]
        if (!identity) return
        const parameters = (identity.parameters ??= {})
        const consumed = (parameters['consumed-services'] ??= [])
        const dbName = `${readProject().appName}-db`
        if (!consumed.some(c => c?.['service-instance-name'] === dbName)) {
            consumed.push({ 'service-instance-name': dbName })
        }
        await writeYAML('chart/values.yaml', js)
    }

    async _existingIdentityName() {
        const { readYAML } = require('../../../util/fs')
        const doc = await readYAML('mta.yaml')
        if (!doc) return undefined
        const js = doc.toJS?.() ?? doc
        const resources = js?.resources || []
        const found = resources.find(r => r?.parameters?.service === 'identity')
        return found?.name
    }

    async _consumeServerlessFrom(identityName) {
        const { readYAML, writeYAML } = require('../../../util/fs')
        const doc = await readYAML('mta.yaml')
        if (!doc) return
        const js = doc.toJS()
        const resource = (js.resources || []).find(r => r.name === identityName)
        if (!resource) return
        const config = ((resource.parameters ??= {}).config ??= {})
        const consumed = (config['consumed-services'] ??= [])
        const dbName = `${readProject().appName}-db`
        if (!consumed.some(c => c?.['service-instance-name'] === dbName)) {
            consumed.push({ 'service-instance-name': dbName })
        }
        const after = (resource['processed-after'] ??= [])
        if (!after.includes(dbName)) after.push(dbName)
        await writeYAML('mta.yaml', js)
    }

    async _alignSidecarDbKind() {
        const sidecarPackageJson = join('mtx', 'sidecar', 'package.json')
        if (!exists(sidecarPackageJson)) return
        const packageJson = await read(sidecarPackageJson)
        const requires = ((packageJson.cds ??= {}).requires ??= {})
        const profile = (requires['[production]'] ??= {})
        profile.db = 'hana-serverless'
        const mt = (requires.multitenancy ??= {})
        mt.serverless = { ...mt.serverless, autoSubscription: true }
        await write(sidecarPackageJson, packageJson, { spaces: 2 })
    }
}
